//! Per-DAO query modules. One file per entity (or entity cluster).
//! Each module exposes an `Xxx<E>` handle reached via an `XxxEntry`
//! trait blanket-impl'd on every [`QueryExecutor`](crate::QueryExecutor)
//! — both generated by the [`query_handle!`](crate::query_handle) macro.
//!
//! Inherent methods on the handle (in the same file) hard-code
//! DAO-specific column knowledge, state filters, or partition-stable
//! invariants — anything that couldn't be expressed safely in a
//! generic trait.
//!
//! For DAO-generic queries (latest-at-time, current-view reads,
//! chunked fetches, recursive walks), see [`crate::generic`].

pub mod dependency;
pub mod execution;
pub mod function_runs;
pub mod metrics;
pub mod pointers;
pub mod session;
pub mod table_data_versions;

#[cfg(test)]
mod schema_consistency;
